display.text:
/**
 * Правило по умолчанию: молчание = согласие.
 *
 * Если на запрос разрешения не ответили за OPENCODE_AUTO_APPROVE_MS
 * (по умолчанию 10 секунд), запрос считается одобренным и действие
 * выполняется. Пока пользователь молчит, окно вопроса остаётся открытым —
 * он может ответить в любой момент раньше таймера, и тогда таймер
 * отменяется, а его выбор (в т.ч. запретить) побеждает.
 *
 * Отключить: OPENCODE_AUTO_APPROVE_MS=0
 * Отключить совсем: убрать "permission" из opencode.jsonc или удалить файл.
 */
import type { Plugin } from "@opencode-ai/plugin"

const TIMEOUT_MS = (() => {
  const raw = process.env.OPENCODE_AUTO_APPROVE_MS
  if (raw === undefined || raw === "") return 10_000
  const parsed = Number(raw)
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 10_000
})()

export default (async ({ client }) => {
  const timers = new Map<string, ReturnType<typeof setTimeout>>()

  const log = (message: string) => {
    try {
      void client.app.log({
        body: { service: "auto-approve", level: "info", message },
      })
    } catch {
      // Логирование не должно ломать разрешение.
    }
  }

  const cancel = (id: string) => {
    const timer = timers.get(id)
    if (timer) {
      clearTimeout(timer)
      timers.delete(id)
    }
  }

  return {
    // Ответили раньше таймера — отменяем автоодобрение, выбор пользователя
    // остаётся в силе.
    event: async ({ event }) => {
      const p = event.properties as Record<string, any> | undefined
      if (!p) return
      if (event.type === "permission.replied") cancel(p.permissionID ?? p.id)
      if (event.type === "permission.updated" && p.id) cancel(p.id)
      if (event.type === "permission.asked" && p.id && p.metadata?.replied) cancel(p.id)
    },

    "permission.ask": async (input, output) => {
      // Правила из opencode.json уже решили исход — таймер не нужен.
      if (output.status !== "ask") return

      cancel(input.id)

      const timer = setTimeout(() => {
        timers.delete(input.id)
        if (output.status === "ask") {
          output.status = "allow"
          log(`нет ответа ${TIMEOUT_MS} мс — разрешено автоматически: ${input.type}`)
        }
      }, TIMEOUT_MS)
      // Не держать процесс ради таймера.
      (timer as { unref?: () => void }).unref?.()
      timers.set(input.id, timer)
    },
  }
}) satisfies Plugin

