input.content:
// Проверка правила «молчание = согласие» без сборки opencode.
// TS-типы снимаются точечно, логика таймера прогоняется как есть.
// Запуск: node ~/.config/opencode/test/auto-approve.test.mjs
import { readFileSync, writeFileSync, mkdtempSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import assert from "node:assert/strict"

const SRC = new URL("../plugins/auto-approve.ts", import.meta.url)

const toJs = (ts) =>
  ts
    .replace(/^import type .*$/m, "")
    .replace(/\}\)\s*satisfies Plugin/, "})")
    .replace(/new Map<string, ReturnType<typeof setTimeout>>\(\)/, "new Map()")
    .replace(/\(id: string\)/g, "(id)")
    .replace(/\(message: string\)/g, "(message)")
    .replace(/\(timer as \{ unref\?: \(\) => void \}\)/g, "(timer)")
    .replace(/event\.properties as \{ permissionID\?: string \}/g, "event.properties")

const logs = []
const client = { app: { log: (o) => logs.push(o.body.message) } }

const load = async (env) => {
  const dir = mkdtempSync(join(tmpdir(), "autoapprove-"))
  const file = join(dir, "plugin.mjs")
  writeFileSync(file, toJs(readFileSync(SRC, "utf8")))
  process.env.OPENCODE_AUTO_APPROVE_MS = env
  const mod = await import(file)
  return mod.default({ client })
}

const wait = (ms) => new Promise((r) => setTimeout(r, ms))

// 1. Молчание дольше таймера -> allow.
{
  const hooks = await load("120")
  const out = { status: "ask" }
  await hooks["permission.ask"]({ id: "p1", type: "bash" }, out)
  assert.equal(out.status, "ask", "окно вопроса должно оставаться открытым сразу")
  await wait(40)
  assert.equal(out.status, "ask", "до истечения таймера решение не принимается")
  await wait(140)
  assert.equal(out.status, "allow", "молчание = согласие")
  assert.ok(logs.some((m) => m.includes("bash")), "автоодобрение попало в лог")
  console.log("ok: молчание > таймера -> allow")
}

// 2. Ответ раньше таймера -> таймер отменён, решение пользователя остаётся.
{
  const hooks = await load("120")
  const out = { status: "ask" }
  await hooks["permission.ask"]({ id: "p2", type: "edit" }, out)
  await hooks.event({ event: { type: "permission.replied", properties: { permissionID: "p2" } } })
  out.status = "deny"
  await wait(200)
  assert.equal(out.status, "deny", "ответ пользователя не перебивается таймером")
  console.log("ok: ответ раньше таймера -> таймер отменён")
}

// 3. Уже разрешено правилом из конфига -> таймер не трогает решение.
{
  const hooks = await load("60")
  const out = { status: "allow" }
  await hooks["permission.ask"]({ id: "p3", type: "bash" }, out)
  await wait(120)
  assert.equal(out.status, "allow")
  console.log("ok: готовое решение не переигрывается")
}

// 4. Два запроса подряд не мешают друг другу.
{
  const hooks = await load("80")
  const a = { status: "ask" }
  const b = { status: "ask" }
  await hooks["permission.ask"]({ id: "a", type: "bash" }, a)
  await hooks["permission.ask"]({ id: "b", type: "edit" }, b)
  await hooks.event({ event: { type: "permission.replied", properties: { permissionID: "b" } } })
  b.status = "deny"
  await wait(140)
  assert.equal(a.status, "allow", "первый запрос одобрен по таймеру")
  assert.equal(b.status, "deny", "второй остался с ответом пользователя")
  console.log("ok: параллельные запросы изолированы")
}

// 5. По умолчанию 10 секунд (значение по умолчанию в коде).
{
  const ts = readFileSync(SRC, "utf8")
  assert.match(ts, /return 10_000/, "в коде должен быть дефолт 10 секунд")
  console.log("ok: дефолт 10 секунд")
}

console.log("\nвсе проверки прошли")

