const out = process.env.OPENCODE_PROBE_OUT
if (out) {
  appendFileSync(
    out,
    JSON.stringify(
      {
        clientKeys: Object.keys((globalThis as any).__probeClient ?? {}),
        version: "1",
      },
      null,
      2,
    ) + "\n",
  )
}

export default (async (ctx: any) => {
  if (out) {
    appendFileSync(out, "plugin input keys: " + JSON.stringify(Object.keys(ctx)) + "\n")
    const c = ctx.client
    appendFileSync(out, "client proto: " + Object.getPrototypeOf(c)?.constructor?.name + "\n")
    appendFileSync(out, "client keys: " + JSON.stringify(Object.keys(c)) + "\n")
    appendFileSync(
      out,
      "permission namespace: " +
        JSON.stringify(c?.permission ? Object.keys(c.permission) : null) +
        "\n",
    )
    appendFileSync(
      out,
      "has postSessionIdPermissionsPermissionId: " +
        typeof c?.postSessionIdPermissionsPermissionId +
        "\n",
    )
  }
  return {}
}) as any

import { appendFileSync } from "node:fs"

const out = process.env.OPENCODE_PROBE_OUT!

export default (async (ctx: any) => {
  return {
    event: async ({ event }: any) => {
      if (!String(event?.type ?? "").startsWith("permission")) return
      let note = `EVENT ${event.type} ${JSON.stringify(event.properties)}`
      try {
        const res = await ctx.client.postSessionIdPermissionsPermissionId({
          path: { id: event.properties?.sessionID, permissionID: event.properties?.id },
          body: { response: "always" },
          query: { directory: ctx.directory },
        })
        note += ` -> reply ok: ${JSON.stringify(res).slice(0, 160)}`
      } catch (e: any) {
        note += ` -> reply failed: ${JSON.stringify(e).slice(0, 160)}`
      }
      appendFileSync(out, note + "\n")
    },
  }
}) as any

