/**
 * Правило по умолчанию: молчание = согласие.
 *
 * opencode не спрашивает разрешения у плагина напрямую: сервер публикует
 * событие `permission.asked`, а решить запрос должен клиент через
 * `POST /session/{id}/permissions/{permissionID}`. Поэтому плагин слушает
 * событие и, если за OPENCODE_AUTO_APPROVE_MS (по умолчанию 10 секунд)
 * никто не ответил, отвечает сам — reply "always", то есть «полный доступ»
 * для этого правила: такие же команды дальше не спрашивают.
 *
 * Пока пользователь молчит, окно вопроса остаётся открытым: ответить можно
 * в любой момент раньше таймера, тогда таймер снимается по событию
 * `permission.replied` и решает человек.
 *
 * Отключить: OPENCODE_AUTO_APPROVE_MS=0 (или удалить файл).
 */
import type { Plugin } from "@opencode-ai/plugin"

const TIMEOUT_MS = (() => {
  const raw = process.env.OPENCODE_AUTO_APPROVE_MS
  if (raw === undefined || raw === "") return 10_000
  const parsed = Number(raw)
  // Мусор в переменной — дефолт. 0 — правило выключено (таймер не ставится).
  if (!Number.isFinite(parsed) || parsed < 0) return 10_000
  return parsed
})()

export default (async ({ client, directory }) => {
  const timers = new Map<string, ReturnType<typeof setTimeout>>()

  const log = (message: string, level: "debug" | "info" = "info") => {
    try {
      void client.app.log({ body: { service: "auto-approve", level, message } })
    } catch {
      // Логирование не должно ломать разрешение.
    }
  }

  const cancel = (id: string | undefined) => {
    if (!id) return
    const timer = timers.get(id)
    if (!timer) return
    clearTimeout(timer)
    timers.delete(id)
  }

  // setTimeout возвращает number в браузерных тайпax и Timeout в node.
  // Отдельная функция, а не `(t as X).unref()` строкой ниже: строка,
  // начинающаяся с `(`, продолжает предыдущее выражение и падает по TDZ.
  const unref = (t: unknown) => {
    ;(t as { unref?: () => void } | undefined)?.unref?.()
  }

  return {
    event: async ({ event }) => {
      const props = event.properties as Record<string, any>

      // Ответили раньше таймера — человек решил, его выбор остаётся в силе.
      if (event.type === "permission.replied") {
        if (props?.reply === "always") log(`ответ пользователя: ${props?.reply}`)
        cancel(props?.requestID)
        return
      }

      if (event.type !== "permission.asked") return
      if (TIMEOUT_MS === 0) return

      const id = props?.id as string | undefined
      const sessionID = props?.sessionID as string | undefined
      if (!id || !sessionID) return

      log(`вопрос: ${props?.permission} ${JSON.stringify(props?.patterns)}`, "debug")

      // Тот же запрос второй раз — старый таймер снимаем.
      cancel(id)

      const timer = setTimeout(() => {
        timers.delete(id)
        void (async () => {
          try {
            await client.postSessionIdPermissionsPermissionId({
              path: { id: sessionID, permissionID: id },
              body: { response: "always" },
              query: { directory },
            })
            log(
              `нет ответа ${TIMEOUT_MS} мс — разрешено автоматически: ${props?.permission} ${JSON.stringify(props?.patterns)}`,
            )
          } catch (error) {
            // 400 = уже отвечено (пользователь успел раньше). Не шумим.
            log(`не смог ответить сам: ${String(error).slice(0, 200)}`, "debug")
          }
        })()
      }, TIMEOUT_MS)
      unref(timer)
      timers.set(id, timer)
    },
  }
}) satisfies Plugin

// Проверка правила «молчание = согласие» без TUI.
// TS-типы снимаются точечно, логика таймера и ответов прогоняется как есть.
// Запуск: node ~/.config/opencode/test/auto-approve.test.mjs
import { readFileSync, writeFileSync, mkdirSync } from "node:fs"
import { join } from "node:path"
import assert from "node:assert/strict"

const SRC = new URL("../plugins/auto-approve.ts", import.meta.url)
// Временные файлы — только в рабочей папке раннера (MANIFEST.md), не в /tmp.
const WORK = process.env.OPENCODE_TEST_TMP || "/home/runner/hub-work/yomikai/tmp/autoapprove-test"

const toJs = (ts) =>
  ts
    .replace(/^import type .*$/m, "")
    .replace(/\}\)\s*satisfies Plugin/, "})")
    .replace(/new Map<string, ReturnType<typeof setTimeout>>\(\)/, "new Map()")
    .replace(/\(message: string, level: "debug" \| "info" = "info"\)/g, "(message, level = 'info')")
    .replace(/\(id: string \| undefined\)/g, "(id)")
    .replace(/\(t: unknown\)/g, "(t)")
    .replace(/;\(t as \{ unref\?: \(\) => void \} \| undefined\)\?\.unref\?\.\(\)/, "(t && t.unref && t.unref())")

const logs = []
const replies = []
const client = {
  app: { log: (o) => logs.push(o.body.message) },
  postSessionIdPermissionsPermissionId: async (req) => {
    replies.push(req)
    if (req.__fail) throw new Error("400 Bad Request")
    return { data: true }
  },
}

let seq = 0
const load = async (env, dir = "/home/runner/hub-work/yomikai/code") => {
  seq += 1
  const folder = join(WORK, `case-${seq}`)
  mkdirSync(folder, { recursive: true })
  const file = join(folder, "plugin.mjs")
  writeFileSync(file, toJs(readFileSync(SRC, "utf8")))
  process.env.OPENCODE_AUTO_APPROVE_MS = env
  const mod = await import(file)
  return mod.default({ client, directory: dir })
}

const wait = (ms) => new Promise((r) => setTimeout(r, ms))
const asked = (over = {}) => ({
  event: {
    type: "permission.asked",
    properties: {
      id: "per_1",
      sessionID: "ses_1",
      permission: "bash",
      patterns: ["echo hi"],
      metadata: {},
      always: ["echo hi *"],
      ...over,
    },
  },
})
const replied = (requestID, reply = "once") => ({
  event: { type: "permission.replied", properties: { sessionID: "ses_1", requestID, reply } },
})

// 1. Молчание дольше таймера -> ответ "always" с правильными id.
{
  const hooks = await load("120")
  await hooks.event(asked())
  await wait(40)
  assert.equal(replies.length, 0, "до истечения таймера отвечать нельзя")
  await wait(150)
  assert.equal(replies.length, 1, "после молчания плагин ответил сам")
  assert.deepEqual(replies[0].path, { id: "ses_1", permissionID: "per_1" })
  assert.equal(replies[0].body.response, "always", "ответ = полный доступ для правила")
  assert.equal(replies[0].query.directory, "/home/runner/hub-work/yomikai/code")
  assert.ok(logs.some((m) => m.includes("разрешено автоматически")), "автоодобрение попало в лог")
  console.log("ok: молчание > таймера -> reply always")
}

// 2. Ответ раньше таймера -> плагин молчит, таймер снят.
{
  const hooks = await load("120")
  await hooks.event(asked())
  await hooks.event(replied("per_1"))
  await wait(200)
  assert.equal(replies.length, 0, "после ответа пользователя плагин не вмешивается")
  console.log("ok: ответ раньше таймера -> таймер снят")
}

// 3. Повторный asked на тот же id не плодит таймеры.
{
  const hooks = await load("80")
  await hooks.event(asked())
  await wait(50)
  await hooks.event(asked())
  await wait(120)
  assert.equal(replies.length, 1, "по одному ответу на запрос, а не по два")
  console.log("ok: повторный вопрос не дублирует ответ")
}

// 4. Два разных запроса изолированы.
{
  const hooks = await load("80")
  await hooks.event(asked({ id: "per_a", patterns: ["a"] }))
  await hooks.event(asked({ id: "per_b", patterns: ["b"] }))
  await hooks.event(replied("per_b", "reject"))
  await wait(150)
  assert.equal(replies.length, 1)
  assert.equal(replies[0].path.permissionID, "per_a", "отвечен только тот, на который не ответили")
  console.log("ok: параллельные запросы изолированы")
}

// 5. Ошибка ответа (пользователь успел раньше) не роняет плагин.
{
  const hooks = await load("50")
